/* From Uiverse.io by PriyanshuGupta28 - Tags: checkbox, docs checkbox, cool checkbox, circle-checkbox */
.__UIV_SCOPE__ .checkbox-wrapper:hover .check {
  stroke-dashoffset: 0;
}

.__UIV_SCOPE__ .checkbox-wrapper {
  position: relative;
  display: inline-block;
  width: 40px;
  height: 40px;
}

.__UIV_SCOPE__ .checkbox-wrapper .background {
  fill: rgb(75, 50, 121);
  transition: ease all 0.6s;
  -webkit-transition: ease all 0.6s;
}

.__UIV_SCOPE__ .checkbox-wrapper .stroke {
  fill: none;
  stroke: #fff;
  stroke-miterlimit: 10;
  stroke-width: 2px;
  stroke-dashoffset: 100;
  stroke-dasharray: 100;
  transition: ease all 0.6s;
  -webkit-transition: ease all 0.6s;
}

.__UIV_SCOPE__ .checkbox-wrapper .check {
  fill: none;
  stroke: #fff;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2px;
  stroke-dashoffset: 22;
  stroke-dasharray: 22;
  transition: ease all 0.6s;
  -webkit-transition: ease all 0.6s;
}

.__UIV_SCOPE__ .checkbox-wrapper input[type=checkbox] {
  position: absolute;
  width: 100%;
  height: 100%;
  left: 0;
  top: 0;
  margin: 0;
  opacity: 0;
  -appearance: none;
  -webkit-appearance: none;
}

.__UIV_SCOPE__ .checkbox-wrapper input[type=checkbox]:hover {
  cursor: pointer;
}

.__UIV_SCOPE__ .checkbox-wrapper input[type=checkbox]:checked + svg .background {
  fill: #421c64;
}

.__UIV_SCOPE__ .checkbox-wrapper input[type=checkbox]:checked + svg .stroke {
  stroke-dashoffset: 0;
}

.__UIV_SCOPE__ .checkbox-wrapper input[type=checkbox]:checked + svg .check {
  stroke-dashoffset: 0;
}
